mkdir -p /tmp/push-gate-check && cat > /tmp/push-gate-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g2-3/bot.mjs';

const base = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
// Tokyo is UTC+9 with no DST. Helper: build a Date from a Tokyo wall-clock time.
const tokyo = (s) => new Date(`${s}+09:00`);
const ok = { allowed: true, reason: null };
const deny = (reason) => ({ allowed: false, reason });

// Quiet hours, Tokyo
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T23:30:00')), deny('quiet_hours'));
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T00:30:00')), deny('quiet_hours'));
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T06:59:00')), deny('quiet_hours'));
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T07:00:00')), ok);   // end is exclusive
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T21:59:00')), ok);   // before start
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T22:00:00')), deny('quiet_hours')); // start inclusive
}
// Quiet window that does not cross midnight
{
  const g = createPushGate();
  const u = { ...base, quietStart: '13:00', quietEnd: '14:00', dailyCap: 9 };
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T12:59:00')), ok);
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T13:00:00')), deny('quiet_hours'));
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T14:00:00')), ok);
}
// Equal start and end: no quiet window
{
  const g = createPushGate();
  const u = { ...base, quietStart: '00:00', quietEnd: '00:00' };
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T03:00:00')), ok);
}
// Daily cap, per user-local calendar day
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T08:00:00')), ok);
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T12:00:00')), ok);
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T18:00:00')), ok);
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T19:00:00')), deny('daily_cap_reached'));
  // Next local day, cap resets
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T08:00:00')), ok);
}
// Local midnight is the day boundary, not a rolling 24h window
{
  const g = createPushGate();
  const u = { ...base, quietStart: '00:00', quietEnd: '00:00', dailyCap: 1 };
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T23:50:00')), ok);
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T00:10:00')), ok); // 20 min later, new day
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T00:20:00')), deny('daily_cap_reached'));
}
// Quiet-hours denial does not use up the cap
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 1 };
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T23:00:00')), deny('quiet_hours'));
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T08:00:00')), ok);
  assert.deepEqual(g.attempt(u, tokyo('2026-10-23T09:00:00')), deny('daily_cap_reached'));
}
// dailyCap 0 blocks everything
{
  const g = createPushGate();
  assert.deepEqual(g.attempt({ ...base, dailyCap: 0 }, tokyo('2026-10-22T08:00:00')), deny('daily_cap_reached'));
}
// Timezone is taken from the user, not the host clock or UTC
{
  const g = createPushGate();
  // 2026-10-22T03:00Z is 23:00 on 21 Oct in New York (EDT, UTC-4): inside quiet hours.
  const ny = { id: 'u_ny', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
  assert.deepEqual(g.attempt(ny, new Date('2026-10-22T03:00:00Z')), deny('quiet_hours'));
  // Same instant in Tokyo is 12:00: allowed.
  assert.deepEqual(g.attempt(base, new Date('2026-10-22T03:00:00Z')), ok);
}
// Daily count in NY: two pushes late on 21 Oct NY date, third after NY midnight
{
  const g = createPushGate();
  const ny = { id: 'u_ny2', timeZone: 'America/New_York', quietStart: '00:00', quietEnd: '00:00', dailyCap: 2 };
  assert.deepEqual(g.attempt(ny, new Date('2026-10-22T02:00:00Z')), ok); // 22:00 NY 21 Oct
  assert.deepEqual(g.attempt(ny, new Date('2026-10-22T03:30:00Z')), ok); // 23:30 NY 21 Oct
  assert.deepEqual(g.attempt(ny, new Date('2026-10-22T04:30:00Z')), ok); // 00:30 NY 22 Oct, new day
  assert.deepEqual(g.attempt(ny, new Date('2026-10-22T05:00:00Z')), deny('daily_cap_reached'));
}
// Per-user independence and per-gate independence
{
  const g = createPushGate();
  const a = { ...base, dailyCap: 1 };
  const b = { ...base, id: 'u_other', dailyCap: 1 };
  assert.deepEqual(g.attempt(a, tokyo('2026-10-22T08:00:00')), ok);
  assert.deepEqual(g.attempt(b, tokyo('2026-10-22T08:00:00')), ok);
  assert.deepEqual(g.attempt(a, tokyo('2026-10-22T09:00:00')), deny('daily_cap_reached'));
  const other = createPushGate();
  assert.deepEqual(other.attempt(a, tokyo('2026-10-22T09:00:00')), ok);
}
// Caller can change settings between calls
{
  const g = createPushGate();
  assert.deepEqual(g.attempt({ ...base, dailyCap: 1 }, tokyo('2026-10-22T08:00:00')), ok);
  assert.deepEqual(g.attempt({ ...base, dailyCap: 5 }, tokyo('2026-10-22T09:00:00')), ok);
}
// Invalid time strings throw
{
  const g = createPushGate();
  assert.throws(() => g.attempt({ ...base, quietStart: '24:00' }, tokyo('2026-10-22T08:00:00')), TypeError);
  assert.throws(() => g.attempt({ ...base, quietEnd: '7am' }, tokyo('2026-10-22T08:00:00')), TypeError);
}
console.log('all checks passed');
EOF
node /tmp/push-gate-check/check.mjs; echo "exit=$?"; node --version
